/**
 * A hit list with its answers.
 */
export interface HitList {
  id: string;
  /**
     * Sequential number of the hit lists, never changed; the data migration keeps the legacy number, so there may be gaps
     * @minimum 1
     */
  number: number;
  /** HL-<number>, derived and never stored */
  code: string;
  activity: ImprovementProjectActivity;
  assessment_date: string;
  created_at: string;
  updated_at: string;
  /** Every key of the Hit List catalog (the legacy camelCase keys), always present: the value when it has the type of its kind, null otherwise. Keys outside the catalog are never answered. Items, in order: washRag, elbowsOut, shoulderHighLow, hungryHead, buttsUp, twistAndShout, horizontalDistance, sitStand, badVibes, contact. */
  answers: HitListAnswers;
}

/**
 * An item of the hit lists listing (the Hit List of the Produção tab). The activity is the one shown for projects: as it is now.
 */
export interface HitListItem {
  id: string;
  /**
     * Sequential number of the hit lists, never changed; the data migration keeps the legacy number, so there may be gaps
     * @minimum 1
     */
  number: number;
  /** HL-<number>, derived and never stored */
  code: string;
  activity: ImprovementProjectActivity;
  assessment_date: string;
  created_at: string;
  updated_at: string;
}

export interface ImprovementProject {
  id: string;
  scope: ImprovementProjectScope;
  /**
     * Sequential number of the scope, assigned on creation, never changed nor reused
     * @minimum 1
     */
  number: number;
  /** RGP-<number> or RGA-<number>, derived and never stored */
  code: string;
  activity: ImprovementProjectActivity;
  date: string;
  concern: string;
  improvement_recommendation: string;
  /** Free text */
  priority: string;
  /** The photo before the improvement, or null when the project has none */
  before_photo: ProjectFile | null;
  /** The photo after the improvement, or null when the project has none */
  after_photo: ProjectFile | null;
  created_at: string;
  updated_at: string;
}

export interface ImprovementProjectInput {
  scope: ImprovementProjectScope;
  /** An existing activity */
  activity_id: string;
  /** Calendar day, without time. It must fall inside a registered period, limits included; with no period registered every date is refused. */
  date: string;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  concern: string;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  improvement_recommendation: string;
  /**
     * Free text, trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  priority: string;
  /** Optional photo before the improvement. jpg, jpeg or png, up to 10485760 bytes (10 MB), any dimensions. At most one file in this part; leaving it out, or sending it with an empty filename, means no photo. */
  before_photo?: Blob | File;
  /** Optional photo after the improvement, with the same rules as before_photo. */
  after_photo?: Blob | File;
}

export interface ImprovementProjectUpdateInput {
  /** An existing activity */
  activity_id: string;
  /** Calendar day, without time. It must fall inside a registered period, limits included; with no period registered every date is refused. */
  date: string;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  concern: string;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  improvement_recommendation: string;
  /**
     * Free text, trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  priority: string;
  /** Optional replacement of the photo before the improvement. jpg, jpeg or png, up to 10485760 bytes (10 MB), any dimensions. At most one file in this part; leaving it out, or sending it with an empty filename, keeps the current photo. */
  before_photo?: Blob | File;
  /** Optional replacement of the photo after the improvement, with the same rules as before_photo. */
  after_photo?: Blob | File;
}

/**
 * A material receipt (RA). It has no activity. The storage key and the authorship never leave the server.
 */
export interface MaterialReceipt {
  id: string;
  /**
     * Sequential number of the RA, independent of RGP and RGA, never reused
     * @minimum 1
     */
  number: number;
  /** RA-<number>, derived and never stored */
  code: string;
  employee: string;
  employee_registry: string;
  date: string;
  /** The receipt form, or null when there is none */
  file: ProjectFile | null;
  created_at: string;
  updated_at: string;
}

export interface MaterialReceiptInput {
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  employee: string;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  employee_registry: string;
  /** Calendar day, without time. It must fall inside a registered period, limits included; with no period registered every date is refused. */
  date: string;
  /** Optional receipt form. doc, docx, ppt, pptx or pdf, up to 26214400 bytes (25 MB). At most one file, in this part only; leaving it out, or sending it with an empty filename, means no form. */
  file?: Blob | File;
}

/**
 * One attachment of a meeting as the contract exposes it. The storage key never leaves the server: the download goes by meeting id and attachment.
 */
export interface MeetingFile {
  /** Original name sent on the upload, also the name of the downloaded file */
  name: string;
  /** Derived from the extension, not from the Content-Type the client sent */
  mime_type: string;
}

export interface Meeting {
  id: string;
  type: MeetingType;
  name: string;
  responsible: string;
  date: string;
  /** Plain text of several lines; line breaks are preserved and no markup is interpreted */
  subject: string;
  /** Free text, as in the legacy system: no fixed set of values */
  status: string;
  /** The signed presence list, or null when the meeting has none */
  presence_list: MeetingFile | null;
  /** The minutes of the meeting, or null when the meeting has none */
  minutes: MeetingFile | null;
  created_at: string;
  updated_at: string;
}

export interface MeetingInput {
  type: MeetingType;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  name: string;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  responsible: string;
  /** Calendar day, without time. It must fall inside a registered period, limits included; with no period registered every date is refused. */
  date: string;
  /**
     * Plain text of several lines, trimmed before validation. Line breaks are preserved and no markup is interpreted.
     * @minLength 1
     * @maxLength 2000
     */
  subject: string;
  /**
     * Free text, trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  status: string;
  /** Optional signed presence list. doc, docx, ppt, pptx or pdf - no spreadsheet - up to 26214400 bytes (25 MB). At most one file in this part. Leaving the part out, or sending it with an empty filename, keeps the meeting without a presence list. */
  presence_list?: Blob | File;
  /** Optional minutes of the meeting. doc, docx, ppt, pptx or pdf - no spreadsheet - up to 26214400 bytes (25 MB). At most one file in this part. Leaving the part out, or sending it with an empty filename, keeps the meeting without minutes. */
  minutes?: Blob | File;
}

/**
 * State of a management plan cell: not_evaluated is the grey of a cell not evaluated yet
 */
export type ManagementPlanCellState = typeof ManagementPlanCellState[keyof typeof ManagementPlanCellState];


export const ManagementPlanCellState = {
  not_evaluated: 'not_evaluated',
  green: 'green',
  yellow: 'yellow',
  red: 'red',
} as const;

/**
 * The four rows of the management plan that are evaluated cell by cell. inputs and outputs are derived from them and never written.
 */
export type ManagementPlanEvaluatedRow = typeof ManagementPlanEvaluatedRow[keyof typeof ManagementPlanEvaluatedRow];


export const ManagementPlanEvaluatedRow = {
  educational: 'educational',
  clinical: 'clinical',
  projects: 'projects',
  management: 'management',
} as const;

export interface ManagementPlanCellInput {
  state: ManagementPlanCellState;
}

export interface ManagementPlanGoalInput {
  /**
     * Score planned for the end of the period
     * @minimum 0
     * @maximum 16
     */
  goal: number;
}

/**
 * The six rows of the grid, in this order, each with the states of levels 1 to 4 (position i is level i + 1). inputs and outputs are derived from the four evaluated rows and are always equal.
 */
export type ManagementPlanRows = {
  /**
     * @minItems 4
     * @maxItems 4
     */
  inputs: ManagementPlanCellState[];
  /**
     * @minItems 4
     * @maxItems 4
     */
  outputs: ManagementPlanCellState[];
  /**
     * @minItems 4
     * @maxItems 4
     */
  educational: ManagementPlanCellState[];
  /**
     * @minItems 4
     * @maxItems 4
     */
  clinical: ManagementPlanCellState[];
  /**
     * @minItems 4
     * @maxItems 4
     */
  projects: ManagementPlanCellState[];
  /**
     * @minItems 4
     * @maxItems 4
     */
  management: ManagementPlanCellState[];
};

export interface ManagementPlan {
  period: Period;
  /** The six rows of the grid, in this order, each with the states of levels 1 to 4 (position i is level i + 1). inputs and outputs are derived from the four evaluated rows and are always equal. */
  rows: ManagementPlanRows;
  /**
     * Number of green cells in the four evaluated rows; inputs and outputs do not count
     * @minimum 0
     * @maximum 16
     */
  score: number;
  /**
     * Score planned for the end of the period; 0 for a plan never changed
     * @minimum 0
     * @maximum 16
     */
  goal: number;
}

/**
 * The five fixed fronts of the program, in the order of the legacy E-Matrix, which is also the order of the listing: ergonomics-team-and-trainings (Equipe de Ergonomia e Treinamentos), procedures-and-materials (Procedimento e Materiais), priority-list (Lista de Prioridades), ergonomic-projects (Projetos Ergonomicos) and improvement-review-and-control (Revisao e Controle de Melhorias). Several items may share a type.
 */
export type ProgramType = typeof ProgramType[keyof typeof ProgramType];


export const ProgramType = {
  'ergonomics-team-and-trainings': 'ergonomics-team-and-trainings',
  'procedures-and-materials': 'procedures-and-materials',
  'priority-list': 'priority-list',
  'ergonomic-projects': 'ergonomic-projects',
  'improvement-review-and-control': 'improvement-review-and-control',
} as const;

/**
 * The key of a fixed material, downloaded from GET /programs/materials/{material}: material-specifications (especificacoes-materiais.docx) and ergonomics-procedure (procedimento-ergonomia.docx).
 */
export type ProgramMaterial = typeof ProgramMaterial[keyof typeof ProgramMaterial];


export const ProgramMaterial = {
  'material-specifications': 'material-specifications',
  'ergonomics-procedure': 'ergonomics-procedure',
} as const;

/**
 * The attached file as the contract exposes it. The storage key never leaves the server: the download goes by item id.
 */
export interface ProgramFile {
  /** Original name sent on the upload, also the name of the downloaded file */
  name: string;
  /** Derived from the extension, not from the Content-Type the client sent */
  mime_type: string;
}

export interface Program {
  id: string;
  type: ProgramType;
  question: string;
  /** Plain text; line breaks are \n and markup is literal, never HTML */
  description: string;
  /** Plain text; line breaks are \n and markup is literal, never HTML */
  actions: string;
  responsible: string;
  target_date: string;
  /**
     * @minimum 0
     * @maximum 100
     */
  completed_percentage: number;
  /** The attached file, or null when the item has none */
  file: ProgramFile | null;
  /** The keys of the fixed materials of the item's type, in this order: both for procedures-and-materials, whatever the question says, and an empty list for every other type */
  materials: ProgramMaterial[];
  created_at: string;
  updated_at: string;
}

/**
 * The current score of the program, derived on every read and never stored. Not rounded.
 */
export interface ProgramScore {
  /**
     * Sum of the completed percentages x 5 / (number of items x 100); 0 without items
     * @minimum 0
     * @maximum 5
     */
  value: number;
  /** Always 5 */
  max: number;
  /**
     * value / max x 100, the width of the progress bar
     * @minimum 0
     * @maximum 100
     */
  percentage: number;
  /** True only when there are items and value is max */
  complete: boolean;
}

/**
 * The answer of GET /programs: every item and the score. Not an array, unlike the other listings.
 */
export interface ProgramList {
  /** Ordered by the position of the type in ProgramType, then created_at ascending, then id */
  items: Program[];
  score: ProgramScore;
}

export interface ProgramInput {
  type: ProgramType;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  question: string;
  /**
     * Plain text. \r\n is normalized to \n and the text is trimmed before validation; the limit counts code points
     * @minLength 1
     * @maxLength 5000
     */
  description: string;
  /**
     * Plain text. \r\n is normalized to \n and the text is trimmed before validation; the limit counts code points
     * @minLength 1
     * @maxLength 5000
     */
  actions: string;
  /**
     * Trimmed before validation
     * @minLength 1
     * @maxLength 255
     */
  responsible: string;
  /** Calendar day, without time; past dates are accepted */
  target_date: string;
  /**
     * Integer from 0 to 100 sent as multipart text: only decimal digits, so 50.5, -1 and 1e2 are refused
     * @pattern ^\s*\d+\s*$
     */
  completed_percentage: string;
  /** Optional. doc, docx, ppt, pptx, pdf or zip, up to 26214400 bytes (25 MB). Leaving the part out creates the item without a file. */
  file?: Blob | File;
}

